"""Reusable walker for a Star Wars Battlefront II RVM shader database (ResMeta + ResData).

File image layout (all offsets are into the FULL image, i.e. 16-byte ResMeta prepended):

    @0x00  u32 version, u32 offset, u32 size, u32 maybe_hash
    @0x10 .. 0x10+offset            element payload (blocks, back to back)
    @0x10+offset                    trailer:
        u8[16] guid
        u64    db_hash
        u32    unk1
        u32    counts_len           total number of blocks
        u32    unk3
        u16    unk4
        u16    type_count
        type_count * { u32 name_hash; u32 count; u64 index }
        u64    unk6
        counts_len * u16            element_count per block

Mirrors glacier_resource rvm/reader.rs:
  read()          :62-108   header + trailer parse
  read_blocks()   :110-170  payload walk, in type-table order, block i holding
                            block_counts[i] elements of hash_to_size(name_hash) bytes
  :154            block ref = hash_from_binary(city_hash_64_with_seed(block_data, type_hash))
  :46-48          hash_from_binary(h) = u64::from_be(h & 0x000000ffffffffff)

Element sizes come from rvm_sizes.py (generated by parse_rvm_types.py out of
glacier_resource rvm/types.rs).

Typical use:
    from rvmdb import load
    db = load(r"I:\\NewShader\\work\\tat_dx11_full.bin")
    print(db.tiles_exactly, db.payload_end, db.walk_end)
    i = db.offset_to_block(0x1234)
    print(hex(db.block_hash(i)))
"""

from __future__ import annotations

import bisect
import struct
import sys
from pathlib import Path
from typing import NamedTuple

sys.path.insert(0, str(Path(__file__).resolve().parent))

from cityhash64 import city_hash_64_with_seed, hash_from_binary  # noqa: E402
from rvm_sizes import NAMES, SIZES  # noqa: E402

__all__ = ["Db", "TypeEntry", "Block", "load", "NAMES", "SIZES"]


class TypeEntry(NamedTuple):
    name_hash: int
    count: int          # number of BLOCKS of this type
    index: int          # opaque permutation of 0..type_count-1 (NOT the walk order)
    size: int           # element size in bytes
    name: str
    first_block: int    # index into Db.blocks of this type's first block (walk order)


class Block(NamedTuple):
    """Unpacks as (type_hash, block_index, file_offset, byte_len, element_count)."""
    type_hash: int
    block_index: int    # index of this block within its type group
    file_offset: int    # absolute offset into the full file image
    byte_len: int
    element_count: int


class Db:
    __slots__ = (
        "path", "data", "version", "offset", "size", "maybe_hash",
        "guid", "db_hash", "counts_len", "type_count", "types",
        "block_counts", "blocks", "_by_type", "_starts", "_hash_cache",
        "payload_start", "payload_end", "walk_end", "tiles_exactly", "order",
    )

    # ------------------------------------------------------------------ load

    def __init__(self, path, data: bytes | None = None, order: str = "table"):
        self.path = Path(path) if path is not None else None
        self.data = data if data is not None else self.path.read_bytes()
        d = self.data

        self.version, self.offset, self.size, self.maybe_hash = struct.unpack_from("<4I", d, 0)
        self.payload_start = 0x10
        self.payload_end = 0x10 + self.offset

        t = self.payload_end
        self.guid = d[t:t + 16]
        (self.db_hash,) = struct.unpack_from("<Q", d, t + 16)
        _unk1, self.counts_len, _unk3 = struct.unpack_from("<3I", d, t + 24)
        _unk4, self.type_count = struct.unpack_from("<2H", d, t + 36)

        tt = t + 40
        entries = []
        for i in range(self.type_count):
            nh, cnt, idx = struct.unpack_from("<IIQ", d, tt + i * 16)
            entries.append((nh, cnt, idx))

        after_types = tt + self.type_count * 16
        # u64 unk6 then counts_len * u16
        counts_off = after_types + 8
        self.block_counts = list(
            struct.unpack_from(f"<{self.counts_len}H", d, counts_off)
        )

        self.order = order
        if order == "table":
            walk = list(range(self.type_count))
        elif order == "index":
            # order type groups by the table's `index` column
            walk = sorted(range(self.type_count), key=lambda i: entries[i][2])
        else:
            raise ValueError(f"unknown order {order!r}")

        # ------------------------------------------------------------- walk
        self.types: list[TypeEntry] = []
        self.blocks: list[Block] = []
        self._by_type: dict[int, list[int]] = {}
        starts: list[int] = []

        pos = self.payload_start
        counter = 0
        missing = []
        for ti in walk:
            nh, cnt, idx = entries[ti]
            esz = SIZES.get(nh)
            if esz is None:
                missing.append(nh)
                esz = 0
            first_block = len(self.blocks)
            for b in range(cnt):
                n = self.block_counts[counter]
                blen = n * esz
                self.blocks.append(Block(nh, b, pos, blen, n))
                starts.append(pos)
                self._by_type.setdefault(nh, []).append(len(self.blocks) - 1)
                pos += blen
                counter += 1
            self.types.append(
                TypeEntry(nh, cnt, idx, esz, NAMES.get(nh, f"<unknown {nh:#010x}>"), first_block)
            )

        if missing:
            raise KeyError(
                "no size for RVM type hash(es): "
                + ", ".join(f"{h:#010x}" for h in sorted(set(missing)))
            )

        self._starts = starts
        self.walk_end = pos
        self.tiles_exactly = (pos == self.payload_end) and (counter == self.counts_len)
        self._hash_cache: dict[int, int] = {}

    # --------------------------------------------------------------- queries

    def __len__(self) -> int:
        return len(self.blocks)

    def block_bytes(self, i: int) -> bytes:
        b = self.blocks[i]
        return self.data[b.file_offset:b.file_offset + b.byte_len]

    def block_hash(self, i: int) -> int:
        """Content hash / intra-file handle of block i (reader.rs:154). Cached."""
        h = self._hash_cache.get(i)
        if h is None:
            b = self.blocks[i]
            raw = city_hash_64_with_seed(
                self.data, b.type_hash & 0xFFFFFFFF, b.file_offset, b.byte_len
            )
            h = hash_from_binary(raw)
            self._hash_cache[i] = h
        return h

    def all_block_hashes(self) -> list[int]:
        return [self.block_hash(i) for i in range(len(self.blocks))]

    def hash_index(self) -> dict[int, list[int]]:
        """block_hash -> [block indices]."""
        out: dict[int, list[int]] = {}
        for i in range(len(self.blocks)):
            out.setdefault(self.block_hash(i), []).append(i)
        return out

    def find_blocks_of_type(self, type_hash: int) -> list[int]:
        """Indices into self.blocks of every block whose element type is `type_hash`."""
        return list(self._by_type.get(type_hash, ()))

    def type_entry(self, type_hash: int) -> TypeEntry | None:
        for t in self.types:
            if t.name_hash == type_hash:
                return t
        return None

    def offset_to_block(self, file_offset: int) -> int | None:
        """Index of the block containing `file_offset`, or None if outside the payload."""
        if not (self.payload_start <= file_offset < self.walk_end):
            return None
        i = bisect.bisect_right(self._starts, file_offset) - 1
        # zero-length blocks share a start offset; walk forward to the one that spans it
        while i >= 0 and self.blocks[i].byte_len == 0:
            i -= 1
        if i < 0:
            return None
        b = self.blocks[i]
        if b.file_offset <= file_offset < b.file_offset + b.byte_len:
            return i
        return None

    def element(self, block_i: int, elem_i: int) -> bytes:
        b = self.blocks[block_i]
        esz = SIZES[b.type_hash]
        o = b.file_offset + elem_i * esz
        return self.data[o:o + esz]

    # ---------------------------------------------------------------- report

    def type_stats(self):
        """[(type_hash, name, elem_size, n_blocks, n_elements, total_bytes)] per type."""
        out = []
        for t in self.types:
            idxs = self._by_type.get(t.name_hash, ())
            nel = sum(self.blocks[i].element_count for i in idxs)
            nby = sum(self.blocks[i].byte_len for i in idxs)
            out.append((t.name_hash, t.name, t.size, t.count, nel, nby))
        return out


def load(path, order: str = "table") -> Db:
    return Db(path, order=order)


if __name__ == "__main__":
    import sys

    if len(sys.argv) < 2:
        sys.exit("usage: rvmdb.py <shader database file>")
    p = sys.argv[1]
    for order in ("table", "index"):
        try:
            db = Db(p, order=order)
        except Exception as exc:  # noqa: BLE001
            print(f"{order:>6}: FAILED {exc}")
            continue
        print(f"{order:>6}: blocks={len(db)} walk_end={db.walk_end:#x} "
              f"payload_end={db.payload_end:#x} delta={db.walk_end - db.payload_end} "
              f"tiles_exactly={db.tiles_exactly}")
